import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import Link from 'flarum/common/components/Link';
import PostPreview from './PostPreview';
export default class ShareSettingsPage extends ExtensionPage {
  sections() {
    const old = super.sections();

    // Flarum 2.0 standart ayar okuma metodu
    const displayType = this.setting('davwheat-share.share_button_style')();
    old.add('notice', m("div", {
      class: "davwheat_share-Notice"
    }, app.translator.trans('davwheat-share.admin.browser_support_notice', {
      a: m(Link, {
        target: "_blank",
        external: true,
        href: "https://caniuse.com/web-share"
      })
    })), 25);

    // GÜNCELLEME: replace() yerine remove() kullanıyoruz
    old.remove('content');
    old.add('preview', m(PostPreview, {
      displayType: displayType
    }), 15);
    old.remove('permissions');
    return old;
  }
}
flarum.reg.add('davwheat-share', 'admin/components/ShareSettingsPage', ShareSettingsPage);